public static void countDown(int num) {
    if (num <= 0) {
        System.out.println("End");
    } else {
        System.out.print(num + " ");
        countDown(num - 1); // recursive call happens after printing
    }
}
// countDown(4); prints: 4 3 2 1 End

public static void counting(int num) {
    if (num <= 0) {
        System.out.println("Start");
    } else {
        counting(num - 1); // recursive call happens before printing
        System.out.print(num + " ");
    }
}
// counting(4); prints:
// Start
// 1 2 3 4
